 const title=placeLabels.map(l=>`${l.leader?`<path class="paper-label-leader" d="${chartPath(l.leader)}"/>`:''}<text class="paper-place-label ${l.major?'major':''} ${l.current?'current':''}" style="font-size:${n(labelScale*(l.major?11:10))}px" data-chart-label="${escape(l.key)}" data-op="${destinationMode?'destination-select':'hex-select'}" data-id="${escape(destinationMode?cells.find(c=>c.key===l.key)?.siteId:l.key)}" x="${n(l.cx)}" y="${n(l.cy)}" text-anchor="middle">${l.lines.map((line,i)=>`<tspan x="${n(l.cx)}" dy="${i?12*labelScale:0}">${escape(line)}</tspan>`).join('')}</text>`).join('');
